package io.livecut.clips;

import static io.livecut.clips.ClipPlanValidator.JSON;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

class AnswerClipContextTests {
    private static JsonNode rows(int count,int step){var rows=JSON.createArrayNode();for(int i=0;i<count;i++)rows.addObject().put("utterance_id","renamed:"+(i*17+41)).put("start_ms",i*step).put("end_ms",(i+1)*step-1).put("text","完整定义与过程"+i).put("source_chunk_id","synthetic");return rows;}
    private static JsonNode project(JsonNode rows,List<String> ids){return AnswerClipSource.project(AnswerClipSourceTests.answer(rows),rows,rows.get(rows.size()-1).path("end_ms").asLong()+1,JSON.valueToTree(ids),"1.1");}
    private static Map<String,Object> expandedOwner(){var owner=AnswerClipSourceTests.owner("u4");var frozen=JSON.readTree(String.valueOf(owner.get("source_json")));var source=AnswerClipSource.project(frozen.path("answer_result"),frozen.path("utterances"),8000,JSON.valueToTree(List.of("u4")),"1.1");owner.put("source_answer_json",ClipRequestService.canonicalJson(source));owner.put("source_answer_hash",ClipRequestService.sha(String.valueOf(owner.get("source_answer_json"))));return owner;}

    @Test void contextUsesEightWholeNeighborsAndKeepsSelectedOccurrence(){var rows=rows(60,10000);var selected=List.of(rows.get(24).path("utterance_id").asText(),rows.get(25).path("utterance_id").asText());var source=project(rows,selected);assertEquals(18,source.path("context_utterance_ids").size());assertEquals(rows.get(16).path("utterance_id"),source.path("context_utterance_ids").get(0));assertEquals(rows.get(33).path("utterance_id"),source.path("context_utterance_ids").get(17));assertEquals(JSON.valueToTree(selected),source.path("utterance_ids"));}
    @Test void timeLimitStopsBeforeAnEntireSentenceInsteadOfCuttingIt(){var rows=rows(30,20000);var id=rows.get(15).path("utterance_id").asText();var source=project(rows,List.of(id));assertEquals(rows.get(9).path("utterance_id"),source.path("context_utterance_ids").get(0));((ObjectNode)rows.get(9)).put("start_ms",179999);var bounded=project(rows,List.of(id));assertEquals(rows.get(10).path("utterance_id"),bounded.path("context_utterance_ids").get(0));}
    @Test void utf16CapBlocksDirectionWithoutSkippingToEarlierSentences(){var rows=rows(20,10000);((ObjectNode)rows.get(10)).put("text","😀".repeat(5998));((ObjectNode)rows.get(9)).put("text","不可截断的长句");((ObjectNode)rows.get(11)).put("text","短句");var source=project(rows,List.of(rows.get(10).path("utterance_id").asText()));assertEquals(JSON.valueToTree(List.of(rows.get(10).path("utterance_id").asText(),rows.get(11).path("utterance_id").asText())),source.path("context_utterance_ids"));}
    @Test void distantAnchorsRemainPinnedWithinGlobalSeventyTwoSentenceLimit(){var rows=rows(500,1000);List<String> selected=new ArrayList<>();for(int i=10;i<490;i+=20)selected.add(rows.get(i).path("utterance_id").asText());var source=project(rows,selected);assertEquals(72,source.path("context_utterance_ids").size());var actual=new HashSet<String>();source.path("context_utterance_ids").forEach(id->actual.add(id.asText()));assertTrue(actual.containsAll(selected));}
    @Test void storedVersionsBindProjectionPromptIndexAndOriginalReviewPermissions(){var legacy=AnswerClipSourceTests.owner("u4");var expanded=expandedOwner();var old=AnswerClipSource.stored(legacy).source();var fresh=AnswerClipSource.stored(expanded).source();assertEquals("1.0",old.path("schema_version").asText());assertEquals(3,old.path("context_utterance_ids").size());assertEquals(8,fresh.path("context_utterance_ids").size());assertNotEquals(AnswerClipSource.indexHash(legacy,old),AnswerClipSource.indexHash(expanded,fresh));assertEquals(1,AnswerClipSource.requiredProtocol(AnswerClipSource.stored(legacy)));assertEquals(5,AnswerClipSource.requiredProtocol(AnswerClipSource.stored(expanded)));var plan=AnswerClipSourceTests.plan(expanded,"NEEDS_REVIEW");((ObjectNode)plan.path("provenance")).put("prompt_version",AnswerClipSource.CONTEXT_PROMPT);assertDoesNotThrow(()->ClipPlanValidator.validate(plan,expanded,true));((ObjectNode)plan.path("outputs").get(0)).put("enabled",true);assertEquals("INVALID_CLIP_PLAN",AnswerClipSourceTests.failure(()->ClipPlanValidator.validate(plan,expanded,true)));}
    @Test void pythonAndJavaAgreeOnSharedSyntheticProjectionAndCanonicalIndex()throws Exception{var fixture=JSON.readTree(Files.readString(Path.of("../fixtures/anchor-context-v2.json")));var rows=fixture.path("utterances");var source=fixture.path("answer_source");var projected=AnswerClipSource.project(AnswerClipSourceTests.answer(rows),rows,source.path("duration_ms").asLong(),source.path("utterance_ids"),"1.1");assertEquals(source.path("context_utterance_ids"),projected.path("context_utterance_ids"));Map<String,Object> owner=Map.of("source_json",JSON.writeValueAsString(Map.of("utterances",rows)),"source_hash",source.path("source_hash").asText(),"transcript_hash",source.path("transcript_hash").asText());assertEquals(fixture.path("index_hash").asText(),AnswerClipSource.indexHash(owner,source));}
}
